def choose_move(observation):
    # Defensive defaults
    x = observation.get("player_x", 0)
    y = observation.get("player_y", 0)
    # Determine a simple robust policy that tends to stay central and avoid edges,
    # while also pursuing nearby resources or opponents if present.
    # Look for nearby entities with common keys.
    dx = 0
    dy = 0

    # Prefer moving toward nearest resource if available
    resource = observation.get("resources") or []
    if isinstance(resource, list) and resource:
        # Each resource entry assumed as [rx, ry] or dict with x,y
        nearest = None
        best_dist = float('inf')
        for r in resource:
            if isinstance(r, dict):
                rx = r.get("x", 0)
                ry = r.get("y", 0)
            elif isinstance(r, (list, tuple)) and len(r) >= 2:
                rx, ry = r[0], r[1]
            else:
                continue
            dist = abs(rx - x) + abs(ry - y)
            if dist < best_dist:
                best_dist = dist
                nearest = (rx, ry)
        if nearest is not None and best_dist > 0:
            rx, ry = nearest
            if rx > x:
                dx = 1
            elif rx < x:
                dx = -1
            if ry > y:
                dy = 1
            elif ry < y:
                dy = -1
            # If already aligned in one axis, the other may stay zero
            if dx != 0 and dy != 0:
                # keep sign but normalize to step max 1
                pass

    # If no resource moved, look for opponents to pursue
    if dx == 0 and dy == 0:
        opponents = observation.get("opponents") or []
        if isinstance(opponents, list) and opponents:
            nearest = None
            best_dist = float('inf')
            for o in opponents:
                if isinstance(o, dict):
                    ox = o.get("x", 0)
                    oy = o.get("y", 0)
                elif isinstance(o, (list, tuple)) and len(o) >= 2:
                    ox, oy = o[0], o[1]
                else:
                    continue
                dist = abs(ox - x) + abs(oy - y)
                if dist < best_dist:
                    best_dist = dist
                    nearest = (ox, oy)
            if nearest is not None and best_dist > 0:
                ox, oy = nearest
                if ox > x:
                    dx = 1
                elif ox < x:
                    dx = -1
                if oy > y:
                    dy = 1
                elif oy < y:
                    dy = -1

    # If still no movement decided, try to stay near center or avoid edges
    if dx == 0 and dy == 0:
        # Attempt to move toward center (0,0) from current position if fields available
        center_x = observation.get("center_x", 0)
        center_y = observation.get("center_y", 0)
        if center_x is None: center_x = 0
        if center_y is None: center_y = 0
        if center_x > x:
            dx = 1
        elif center_x < x:
            dx = -1
        if center_y > y:
            dy = 1
        elif center_y < y:
            dy = -1

    # Bounds protection: ensure dx,dy in -1,0,1
    if dx not in (-1, 0, 1):
        dx = 0
    if dy not in (-1, 0, 1):
        dy = 0

    return [dx, dy]

