def choose_move(observation):
    # Basic safe defaults
    wx = observation.get("grid_width", 0)
    wy = observation.get("grid_height", 0)
    x = observation.get("self_position", [0, 0])[0]
    y = observation.get("self_position", [0, 0])[1]
    ox = observation.get("opponent_position", [0, 0])[0]
    oy = observation.get("opponent_position", [0, 0])[1]

    # Try to move away from opponent slightly and toward center if possible
    dx = 0
    dy = 0

    # Centering heuristic
    cx = wx // 2
    cy = wy // 2
    if x < cx:
        dx = 1
    elif x > cx:
        dx = -1
    if y < cy:
        dy = 1
    elif y > cy:
        dy = -1

    # If near opponent, bias away
    if abs(x - ox) + abs(y - oy) <= 2:
        if x <= ox:
            dx = -1
        else:
            dx = 1
        if y <= oy:
            dy = -1
        else:
            dy = 1

    # Bound moves to grid
    nx = max(0, min(wx - 1, x + dx))
    ny = max(0, min(wy - 1, y + dy))

    # If no movement chosen due to bounds, stay
    if nx == x and ny == y:
        return [0, 0]
    return [nx - x, ny - y]
